import heapq


def leastLossFactor(n, links, src, dst):
    LIMIT = 2 ** 31 - 1
    adj = [[] for _ in range(n)]
    for a, b, q in links:
        adj[a].append((b, q))
        adj[b].append((a, q))
    best = [None] * n
    best[src] = 1
    heap = [(1, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > best[u]:
            continue
        if u == dst:
            return d
        for v, q in adj[u]:
            nd = d * q
            if nd <= LIMIT and (best[v] is None or nd < best[v]):
                best[v] = nd
                heapq.heappush(heap, (nd, v))
    return -1
